"""Damage rule demonstration, independent of Unity."""

def damage(attack: int, defense: int) -> int:
    if attack < 0 or defense < 0:
        raise ValueError("attack and defense must be non-negative")
    return max(1, attack - defense)

import unittest
from Game.rules import damage

class DamageTests(unittest.TestCase):
    def test_normal(self): self.assertEqual(damage(12, 4), 8)
    def test_minimum(self): self.assertEqual(damage(3, 7), 1)
    def test_zero(self): self.assertEqual(damage(0, 0), 1)
    def test_negative_attack(self):
        with self.assertRaises(ValueError): damage(-1, 0)
    def test_negative_defense(self):
        with self.assertRaises(ValueError): damage(0, -1)
